-- Read-only curated start questions for the six published and four legacy personas.
-- Transcript and profile memory are deliberately NOT stored in this table.
-- Runtime mirrors this versioned bank in lib/coaching/coach-opening-protocol.mjs.
create table if not exists app_private.my_coach_opening_questions (
  version text not null,
  persona_id text not null,
  step_key text not null,
  variant_index smallint not null check (variant_index between 1 and 4),
  prompt_i18n jsonb not null check (prompt_i18n ?& array['en','ru','es']),
  review_status text not null default 'curated' check(review_status='curated'),
  primary key(persona_id,step_key,variant_index),
  constraint my_coach_opening_step check(step_key in ('invitation','name','continuity','focus','feelings','confirmation')),
  constraint my_coach_opening_persona check(persona_id in ('mira','max','sofia','alex','merlin','harry','lea','noah','iris','ray'))
);
alter table app_private.my_coach_opening_questions enable row level security;
alter table app_private.my_coach_opening_questions force row level security;
revoke all on app_private.my_coach_opening_questions from public, anon, authenticated;
comment on table app_private.my_coach_opening_questions is
 'Curated static My Coach onboarding questions only; not a user data or session table. 4 variants per persona/step in RU/EN/ES.';
on conflict(persona_id,step_key,variant_index) do update set
  version=excluded.version,prompt_i18n=excluded.prompt_i18n
where app_private.my_coach_opening_questions.version is distinct from excluded.version;
